questionvariables.text:
/* Reverse engineer to ensure clean integer limits */
lower_val : rand_with_step(-5, -1, 1);
upper_val : rand_with_step(1, 5, 1);

a : rand_with_step(2, 5, 1);
b : rand_with_step(1, 7, 1);

/* Calculate outer bounds to form L < ax - b <= U */
L : a * lower_val - b;
U : a * upper_val - b;

/* Target Answers */
ta1 : lower_val;
ta2 : upper_val;
ta3 : [lower_val, 0]; /* The open circle glider */
ta4 : [upper_val, 0]; /* The closed circle glider */

feedbackvariables.text:
/* Extract the x-coordinates. Open circle is graph_open, Closed circle is graph_closed */
graph_open : ans3[1];
graph_closed : ans4[1];
